                  backgroundColor: currentPage === "catalog" ? "#2563eb" : "#374151",
                  color: "#fff",
                  border: "none",
                  borderRadius: "4px",
                  padding: "6px 12px",
                  cursor: "pointer",
                  fontSize: "13px",
                  fontWeight: "bold",
                }}
